// Authored assessment bank. The first pair is the key in source; output positions
// are rotated here and shuffled independently for each browser attempt.
const questions = [];
const serial = {};
function mc(chapter, topic, section, prompt, reason, choices, pool='practice', source='') {
  const n=(serial[`${pool}-${chapter}`]=(serial[`${pool}-${chapter}`]||0)+1);
  const offset=(questions.length*3+chapter)%choices.length;
  const rotated=choices.slice(offset).concat(choices.slice(0,offset));
  questions.push({id:`${pool}-${chapter}-${n}`,chapter,topic,section,prompt,reason,options:rotated.map(c=>c[0]),analysis:rotated.map(c=>c[1]),answer:(choices.length-offset)%choices.length,type:'mc',pool,source:source||`Materi modul ${chapter}; elaborasi kasus baru.`});
}
function tf(chapter,topic,section,prompt,answer,reason,pool='practice',source='') {
  const n=(serial[`${pool}-${chapter}`]=(serial[`${pool}-${chapter}`]||0)+1);
  questions.push({id:`${pool}-${chapter}-${n}`,chapter,topic,section,prompt,reason,options:['Benar','Salah'],analysis:answer?[reason,'Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit.']:['Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.',reason],answer:answer?0:1,type:'tf',pool,source:source||`Materi modul ${chapter}; elaborasi kasus baru.`});
}

mc(1,'Pure EC vs pure-play','s2','Penjual hanya memiliki situs dan gudang. Pesanan serta pembayaran sepatu dilakukan online, lalu sepatu dikirim kurir. Pasangan klasifikasi paling tepat pada dimensi organisasi dan transaksi adalah…','Kanal organisasi dan digitasi transaksi adalah dua sumbu berbeda. Tidak adanya toko retail mendukung pure-play pada definisi materi, sedangkan produk yang dikirim fisik membuat transaksi partial EC. Gudang tidak menggugurkan pure-play.',[
 ['Pure-play; transaksi partial EC','Kanal penjualan online dan pengiriman fisik dapat hadir bersamaan.'],['Click-and-mortar; transaksi pure EC','Gudang bukan toko retail; pemenuhan fisik juga menggugurkan pure EC.'],['Pure-play; transaksi pure EC','Menyamakan kanal online dengan digitasi seluruh proses mengabaikan pengiriman.'],['Brick-and-mortar; transaksi partial EC','Aset gudang tidak berarti kanal penjualan berupa toko fisik.']]);
mc(1,'Relasi transaksi','s3','Sebuah marketplace mempertemukan dua mahasiswa yang menjual-beli kalkulator pribadi. Pada hari yang sama, marketplace menjual paket iklan kepada toko alat tulis. Klasifikasi dua transaksi tersebut berturut-turut adalah…','Pilih unit analisis transaksinya. Penjual dan pembeli kalkulator adalah individu; penjualan layanan iklan berlangsung antara platform bisnis dan toko bisnis. Kehadiran marketplace tidak mengubah identitas pihak pada transaksi kalkulator.',[
 ['C2C kemudian B2B','Relasi barang antarmahasiswa berbeda dari layanan iklan antarbisnis.'],['B2C kemudian C2B','Platform tidak menjadi penjual kalkulator; toko juga bukan konsumen individu.'],['B2B2C kemudian B2C','Tidak ada bukti rantai dua bisnis yang menjual kalkulator dalam kasus.'],['C2C kemudian C2B','Pengiklan adalah bisnis, sehingga layanan platform bukan transaksi konsumen-ke-bisnis.']]);
mc(1,'Framework EC','s4','Tim sudah mempercepat halaman checkout. Namun 12% pesanan yang dibayar dibatalkan karena stok pemasok tidak sinkron. Investasi berikut yang paling langsung menangani mekanisme kegagalan adalah…','Kegagalan berada pada hubungan order, stok dan pemenuhan. Perbaikan perlu menghubungkan data/proses antarpihak. Promosi atau personalisasi dapat memperbesar permintaan tanpa menambah kemampuan memenuhi pesanan.',[
 ['Sinkronisasi stok dan reservasi lintas mitra','Menangani penyebab stok yang dijanjikan tidak tersedia.'],['Segmentasi promosi dan katalog personal','Mengubah relevansi penawaran, bukan konsistensi ketersediaan.'],['Program afiliasi dan akuisisi penjual','Memperluas jaringan tanpa memastikan data stok andal.'],['Redesain konten dan panduan pembayaran','Membantu front end, sementara kegagalan terjadi setelah pembayaran.']]);
mc(1,'Business model canvas','s8','Platform buku kampus mengklaim nilai “edisi tepat, ambil hari ini”. Dari empat perubahan berikut, mana yang paling menguji konsistensi antarblok canvas?','Proposisi nilai tentang edisi dan waktu harus didukung sumber daya data serta aktivitas pemenuhan. Menambah pendapatan atau tampilan tidak membuktikan kemampuan menyampaikan janji. Canvas merupakan hubungan keputusan, bukan daftar fitur.',[
 ['Validasi ISBN dan kapasitas titik pengambilan','Menghubungkan proposisi nilai dengan aktivitas, sumber daya dan kanal.'],['Menambah slot iklan dan paket langganan','Mengubah revenue streams, belum memvalidasi janji produk dan waktu.'],['Memperluas segmen dan mengganti warna merek','Mengubah pasar/presentasi tanpa mendukung fulfillment yang dijanjikan.'],['Menaikkan komisi dan menambah jumlah kategori','Memperbesar potensi pendapatan serta cakupan, bukan ketepatan edisi.']]);
mc(1,'Revenue vs value proposition','s9','Pelanggan membayar Rp40.000 per bulan untuk akses perbandingan pemasok. Platform juga menerima komisi untuk transaksi yang terjadi melalui rujukannya. Pasangan pernyataan paling tepat adalah…','Subscription dan referral commission menjelaskan arus pendapatan. Alasan pelanggan mau membayar adalah nilai pencarian/perbandingan yang diperoleh. Model yang sama dapat memiliki beberapa revenue streams sekaligus.',[
 ['Subscription dan affiliate fee adalah revenue streams','Keduanya menyebut cara platform menerima imbalan.'],['Perbandingan dan subscription adalah customer segments','Keduanya bukan kelompok pelanggan yang dilayani.'],['Affiliate fee dan perbandingan adalah key resources','Komisi adalah penerimaan; kemampuan perbandingan perlu sumber daya pendukung.'],['Subscription dan komisi adalah value propositions','Cara menarik uang berbeda dari manfaat bagi pelanggan.']]);
mc(1,'Reach, richness, affiliation','s5','Marketplace sudah memuat satu juta SKU, tetapi deskripsi kompatibilitas sangat minim. Menambah video instalasi dan filter kecocokan terutama memperbaiki…','Kasus sudah memiliki jangkauan penawaran yang luas. Kekurangannya adalah kedalaman informasi dan dukungan keputusan. Video dan filter terutama meningkatkan richness; efek lain mungkin ada, tetapi bukan pembeda utama.',[
 ['Richness dalam informasi produk','Kedalaman dan relevansi informasi membantu menilai kecocokan.'],['Reach dalam cakupan penjual','Tidak ada penambahan pihak atau perluasan pasar yang dinyatakan.'],['Affiliation dalam struktur kemitraan','Kasus tidak mengubah hubungan atau kerja sama mitra.'],['Digitization dalam bentuk barang','Video tidak mengubah produk fisik menjadi barang digital.']]);
mc(1,'GMV dan unit economics','s9','Marketplace memfasilitasi 100 order, masing-masing Rp200.000. Komisi 5%; biaya variabel platform Rp7.000 per order. Mengabaikan biaya tetap, kontribusi total platform adalah…','GMV Rp20 juta bukan pendapatan yang seluruhnya menjadi hak platform. Komisi = 5% × Rp20 juta = Rp1 juta. Biaya variabel = 100 × Rp7.000 = Rp700.000; kontribusi Rp300.000 sebelum biaya tetap.',[
 ['Rp300.000 sebelum biaya tetap','Pendapatan komisi dikurangi biaya variabel menghasilkan kontribusi ini.'],['Rp1.000.000 sebelum biaya tetap','Ini pendapatan komisi sebelum dikurangi biaya variabel.'],['Rp19.300.000 sebelum biaya tetap','Ini keliru memperlakukan seluruh GMV sebagai pendapatan platform.'],['Rp700.000 sebelum biaya tetap','Ini total biaya variabel, bukan kontribusi pendapatan.']]);
tf(1,'EC dan EB','s1','Dengan definisi EC sempit dan EB luas yang dinyatakan materi, portal pelatihan internal dapat termasuk EB meskipun tidak memproses penjualan kepada pelanggan.',true,'EB mencakup proses internal dan pembelajaran, sedangkan EC sempit menitikberatkan pertukaran komersial. Pernyataan menetapkan definisi dengan jelas sehingga tidak bergantung pada penggunaan EC luas di bagian lain.');
tf(1,'Manfaat dan hasil','s5','Jika biaya akuisisi per pelanggan naik lebih cepat daripada kontribusi pembeliannya, pertumbuhan order saja belum cukup membuktikan model EC makin menguntungkan.',true,'Pertumbuhan volume harus dibandingkan dengan biaya dan margin. Order merupakan aktivitas transaksi; laba memerlukan pendapatan yang menutup biaya terkait. Pernyataan tidak menyatakan pertumbuhan selalu buruk, hanya membatasi inferensi.');
tf(1,'Jaringan dan aktor','s3','Karena perusahaan mengakses katalog pemasok melalui internet publik, transaksi pembelian komponen itu diklasifikasikan B2C, bukan B2B.',false,'Internet adalah kanal jaringan. Identitas serta tujuan transaksi tetap antarorganisasi, sehingga B2B. Penggunaan jaringan publik tidak mengubah pembeli bisnis menjadi konsumen pribadi.');

mc(2,'Peran perantara','s5','Produsen menjual langsung melalui platform, melewati distributor lama. Platform kemudian mengurus pembayaran, reputasi dan pengiriman. Kesimpulan paling lengkap adalah…','Distributor tertentu dihapus, tetapi fungsi matching, trust dan distribusi tetap diperlukan serta dilaksanakan perantara baru. Satu rantai dapat memperlihatkan disintermediation dan reintermediation sekaligus pada peran berbeda.',[
 ['Distributor dilewati; fungsi perantara dibentuk ulang','Menjelaskan perubahan perusahaan dan fungsi dalam rantai.'],['Seluruh intermediasi hilang; platform menjadi pembeli','Platform memfasilitasi layanan, bukan dinyatakan membeli produk.'],['Rantai tetap identik; hanya promosi berpindah media','Pembayaran, reputasi dan fulfillment menunjukkan perubahan peran nyata.'],['Platform menjadi produsen; distributor menjadi portal','Tidak ada bukti platform memproduksi atau distributor menjadi portal.']]);
mc(2,'Struktur pasar','s4','Satu perusahaan membuka portal bagi 40 pemasok untuk mengajukan penawaran atas spesifikasi pembeliannya. Portal dimiliki dan diatur perusahaan tersebut. Klasifikasi terbaik adalah…','Pengendali merupakan satu organisasi pembeli dan calon penjualnya banyak. Itu private buy-side dalam taksonomi materi. Banyak pemasok tidak cukup untuk menyebut public many-to-many.',[
 ['Private marketplace dengan struktur buy-side','Satu pembeli mengatur pasar yang melibatkan banyak pemasok.'],['Public marketplace dengan struktur sell-side','Tidak ada pemilik pihak ketiga atau satu penjual utama.'],['Private marketplace dengan struktur sell-side','Sell-side berpusat pada satu penjual melayani banyak pembeli.'],['Public marketplace dengan struktur many-to-many','Kasus hanya menyebut satu pembeli dan pengendali yang sama.']]);
mc(2,'Dutch vs reverse auction','s8','Seorang penjual menawarkan satu mesin, memulai harga tinggi lalu menurunkannya sampai salah satu pembeli menerima. Pilihan mana paling tepat?','Arah harga menurun tidak menentukan reverse auction. Satu penjual menawarkan barang kepada banyak calon pembeli, dengan mekanisme Dutch auction. Reverse auction menempatkan banyak pemasok bersaing bagi satu pembeli.',[
 ['Dutch auction pada struktur satu penjual','Harga turun sampai diterima, dengan satu penjual sebagai pusat.'],['Reverse auction pada struktur satu pembeli','Tidak ada satu pembeli yang mengundang persaingan banyak pemasok.'],['Double auction pada struktur banyak pihak','Tidak ada banyak penawaran jual yang dicocokkan dengan penawaran beli.'],['English auction dengan penawaran tertutup','English biasanya bid pembeli meningkat; mekanismenya berbeda dari kasus.']]);
mc(2,'Storefront, mall, portal','s6','Situs X berisi direktori 200 toko dan mengirim pengunjung ke situs masing-masing untuk transaksi. Situs Y menjual katalog satu perusahaan. Pasangan paling tepat adalah…','X menggabungkan beberapa toko dengan pola referring mall. Y merupakan storefront satu penjual. Tidak adanya shared checkout tidak mencegah X diklasifikasikan mall dalam bentuk direktori.',[
 ['X referring mall; Y storefront','Jumlah toko dan lokasi penyelesaian transaksi membedakan keduanya.'],['X storefront; Y corporate portal','X bukan toko tunggal dan Y dinyatakan menjual produk.'],['X buy-side exchange; Y shared mall','Tidak ada organisasi pembeli pusat atau kumpulan toko di Y.'],['X storefront; Y public exchange','Kedua label mengabaikan struktur penjual yang disebutkan.']]);
mc(2,'Front end dan back end','s3','Pembeli melihat “pembayaran selesai” tetapi order tidak muncul di gudang. Log gateway menunjukkan pembayaran disetujui. Lokasi investigasi pertama yang paling relevan adalah…','Bukti menunjukkan antarmuka dan otorisasi merespons, tetapi handoff ke fulfillment gagal. Perlu memeriksa pencatatan status order dan integrasi gudang. Tidak cukup menilai tampilan berhasil sebagai bukti seluruh proses selesai.',[
 ['Transisi status order dan integrasi fulfillment','Mengikuti sambungan yang hilang antara pembayaran dan gudang.'],['Warna notifikasi dan susunan menu katalog','Tidak menjelaskan ketiadaan perintah order di gudang.'],['Relevansi iklan dan segmentasi pengunjung','Berada sebelum pembelian, bukan pada kegagalan yang teramati.'],['Ukuran gambar dan peringkat pencarian produk','Memengaruhi discovery, bukan handoff order yang telah dibayar.']]);
mc(2,'Crowdsourcing','s11','Kontes inovasi menerima 5.000 ide. Tim ingin memilih solusi teknis untuk batas biaya dan performa tertentu. Tahap berikut yang paling dapat dipertanggungjawabkan adalah…','Jumlah kontribusi menunjukkan partisipasi, belum membuktikan kelayakan. Solusi perlu dievaluasi dengan kriteria biaya/performa, dapat dimodifikasi, lalu diprioritaskan. Voting dapat menjadi input, bukan pengganti verifikasi teknis.',[
 ['Saring kelayakan, uji kriteria, lalu prioritaskan','Mengubah kontribusi menjadi kandidat yang dapat dibandingkan.'],['Pilih ide terpopuler, lalu tetapkan spesifikasi','Popularitas sebelum verifikasi bisa memilih ide yang tidak layak.'],['Bayar semua ide, lalu tambah jumlah peserta','Kompensasi dan skala tidak menyelesaikan seleksi kualitas.'],['Publikasikan seluruh ide, lalu tutup evaluasi','Penyebaran hasil belum menentukan solusi yang memenuhi batas.']]);
mc(2,'AR vs visual search','s10','Aplikasi A mencari kursi serupa dari foto pengguna. Aplikasi B menampilkan model kursi digital di atas gambar ruang tamu secara langsung. Perbedaan yang paling tepat adalah…','A menggunakan gambar sebagai kueri pencarian. B menambahkan objek digital pada pandangan ruang nyata, sehingga AR. Kedua aplikasi dapat membantu keputusan, tetapi mekanisme representasinya berbeda.',[
 ['A visual search; B augmented reality','Kueri visual berbeda dari overlay objek pada lingkungan nyata.'],['A augmented reality; B virtual reality','A tidak menambah objek ke lingkungan; B tidak menggantinya sepenuhnya.'],['A virtual reality; B visual search','A tidak membuat lingkungan virtual; B menempatkan objek secara visual.'],['A social search; B crowdsourcing','Kasus tidak menyebut relasi sosial atau kontribusi crowd.']]);
tf(2,'Shopping cart','s7','Jika katalog dan keranjang berhasil menampilkan barang, dapat disimpulkan bahwa stok telah direservasi dan pembayaran diselesaikan di back end.',false,'Katalog dan keranjang menyediakan fungsi pemilihan. Reservasi stok serta pemrosesan pembayaran membutuhkan langkah backend yang terpisah. Tampilan pilihan tidak membuktikan transaksi sudah dipenuhi.');
tf(2,'Komunitas dan marketplace','s9','Komunitas profesional dengan keanggotaan terbatas dapat menggunakan wiki dan forum meskipun tidak memiliki mekanisme jual beli.',true,'Komunitas dibedakan oleh kepentingan dan interaksi anggotanya. Marketplace berfungsi memfasilitasi pertukaran pasar. Tools kolaborasi tidak mewajibkan adanya transaksi komersial.');
tf(2,'Metaverse dan interoperabilitas','s10','Sebuah mal 3D dengan avatar dan transaksi otomatis membuktikan bahwa identitas serta asetnya dapat dipindahkan ke setiap dunia virtual lain.',false,'3D, avatar dan transaksi adalah kemampuan platform. Interoperabilitas memerlukan kesesuaian standar, aturan dan dukungan pihak lain; tidak mengikuti secara otomatis dari sifat imersif.');

mc(3,'Omnichannel','s3','Retailer memiliki web dan toko, tetapi stok serta retur tidak terhubung. Pembeli online ditolak saat meminta retur di toko. Perbaikan yang paling langsung menuju omnichannel adalah…','Omnichannel menekankan kesinambungan pengalaman dan integrasi proses. Dua kanal yang berdiri sendiri baru menunjukkan multichannel. Menambah kanal lain tanpa menyatukan order, stok dan kebijakan hanya memperluas fragmentasi.',[
 ['Satukan identitas order, stok, dan prosedur retur','Menyambungkan pengalaman pelanggan dan operasi lintas kanal.'],['Tambahkan akun media sosial dan promosi web','Memperluas titik interaksi tanpa memperbaiki proses retur.'],['Pisahkan harga dan target kedua manajer kanal','Dapat mempertegas konflik jika proses bersama tetap tidak ada.'],['Sediakan katalog toko dalam format unduhan','Menambah informasi, bukan kemampuan pelayanan lintas kanal.']]);
mc(3,'Kesesuaian produk','s1','Dua produk memberi margin identik: e-book standar dan makanan segar dengan jendela kirim dua jam. Perbedaan desain operasi paling penting adalah…','Makanan segar membawa variasi kualitas, umur simpan dan kendala waktu fisik. Katalog sama baiknya tidak meniadakan kebutuhan kapasitas serta kondisi kirim. E-book memerlukan hak akses dan delivery digital, dengan kendala berbeda.',[
 ['Makanan memerlukan kendali kondisi dan slot kirim','Mengatasi risiko mutu serta waktu yang menentukan nilai produk.'],['E-book memerlukan lebih banyak titik pengambilan','Produk digital tidak memerlukan pickup fisik dalam kasus.'],['Makanan cukup memakai ukuran katalog lebih besar','Lebih banyak informasi tidak menjaga kondisi selama pengiriman.'],['E-book harus memakai saluran retail fisik','Tidak ada keharusan kanal fisik untuk produk digital standar.']]);
mc(3,'Integrasi e-tailing','s2','Katalog menunjukkan lima unit stok; tiga order hampir bersamaan diterima masing-masing dua unit. Pembayaran berhasil, tetapi gudang hanya memiliki lima. Kontrol yang paling langsung relevan adalah…','Masalahnya overselling karena total komitmen melebihi ketersediaan. Reservasi dan pemeriksaan konsisten pada proses order menangani sumber kegagalan. Menambah layanan purnajual membantu dampak, tetapi tidak mencegah kejadian.',[
 ['Reservasi stok konsisten saat order dikonfirmasi','Mencegah beberapa order menggunakan stok tersedia yang sama.'],['Penyajian rating penjual saat checkout dimulai','Rating tidak mengatur alokasi stok yang berkompetisi.'],['Pembaruan foto katalog setelah order dibayar','Gambar baru tidak memperbaiki konsistensi jumlah tersisa.'],['Penggantian kurir setelah order diproses gudang','Kurir menangani distribusi barang yang sudah tersedia.']]);
mc(3,'Channel conflict','s11','Produsen memberi diskon web besar, sementara dealer tetap membiayai demo dan layanan. Banyak pelanggan mencoba di dealer lalu membeli web. Pilihan paling menyasar akar konflik adalah…','Dealer menanggung aktivitas yang menciptakan nilai, tetapi transaksi berpindah sehingga kompensasinya hilang. Penyelarasan peran dan insentif menangani konflik ini. Menyamakan harga saja belum membagi biaya atau nilai pelayanan.',[
 ['Atur atribusi layanan dan pembagian imbalan kanal','Menghubungkan kontribusi dealer dengan insentif ekonomi.'],['Tambah variasi banner pada halaman produk web','Memengaruhi promosi, tidak mengganti pendapatan layanan dealer.'],['Hapus informasi lokasi dealer dari katalog web','Mengurangi visibilitas, tetapi tidak menyelesaikan pembagian fungsi.'],['Pisahkan laporan penjualan agar tidak dibandingkan','Menyembunyikan masalah koordinasi, bukan menyelesaikannya.']]);
mc(3,'Escrow dan trust','s10','Pembeli bersedia membayar jika kondisi barang cocok. Penjual enggan mengirim sebelum kepastian dana. Mekanisme yang paling langsung mengurangi risiko pertukaran berurutan adalah…','Escrow menahan dan melepaskan dana menurut syarat yang disepakati. Ini mengatasi siapa harus menyerahkan lebih dahulu. Rating membantu kepercayaan sebelum transaksi, tetapi tidak dengan sendirinya mengatur transfer dana saat sengketa.',[
 ['Escrow dengan bukti penerimaan dan aturan sengketa','Mengatur pelepasan dana serta penyelesaian ketidaksesuaian.'],['Rating rata-rata dengan jumlah ulasan minimal','Memberi sinyal reputasi, tidak menahan dana transaksi.'],['Perbandingan harga dengan ongkir terintegrasi','Membantu penilaian biaya, bukan risiko penyerahan lebih dulu.'],['Notifikasi stok dengan rekomendasi personal','Mendukung relevansi/discovery, bukan pertukaran dana-barang.']]);
mc(3,'Travel online','s5','Dua tiket memiliki harga awal sama. Tiket A tidak dapat diubah dan bagasi berbayar; tiket B lebih fleksibel dengan bagasi termasuk. Pembeli sering mengubah jadwal. Dasar perbandingan terbaik adalah…','Produk travel merupakan janji layanan dengan aturan. Harga awal sama tidak berarti nilai atau biaya total sama. Relevansi fleksibilitas harus dinilai terhadap pola perjalanan pengguna, bukan digeneralisasikan sebagai pilihan terbaik bagi semua.',[
 ['Biaya total dan ketentuan sesuai pola perjalanan','Menghubungkan harga serta fleksibilitas dengan kebutuhan pembeli.'],['Harga awal dan urutan hasil mesin pencari','Mengabaikan biaya tambahan dan risiko perubahan jadwal.'],['Jumlah pengikut dan lama situs beroperasi','Bisa menjadi sinyal lain, tetapi tidak membandingkan isi tiket.'],['Jumlah foto dan tampilan halaman pemesanan','Tidak menunjukkan syarat bagasi atau perubahan tiket.']]);
mc(3,'Online employment','s6','Portal kerja menaikkan jumlah CV masuk tiga kali lipat, tetapi proporsi kandidat yang lolos asesmen menurun. Kesimpulan dan tindakan yang paling tepat adalah…','Jangkauan lebih besar belum berarti matching lebih baik. Perlu mengevaluasi kriteria, informasi lowongan, filter dan asesmen. Jumlah CV adalah input, sedangkan kecocokan kandidat adalah hasil yang berbeda.',[
 ['Uji relevansi matching dan kualitas penyaringan','Menangani penurunan kecocokan, bukan hanya volume pelamar.'],['Anggap efisien karena volume CV meningkat','Menyamakan jangkauan dengan mutu hasil rekrutmen.'],['Hapus asesmen agar rasio kelulusan membaik','Mengubah ukuran tanpa memperbaiki kecocokan kandidat.'],['Naikkan iklan agar penurunan rasio tertutup','Menambah volume belum menyelesaikan masalah kualitas.']]);
tf(3,'Personalisasi dan customization','s11','Menampilkan produk berdasarkan riwayat pengguna dan membuat sepatu sesuai ukuran pesanan merupakan dua bentuk perubahan yang sama: keduanya hanya personalisasi informasi.',false,'Rekomendasi mengubah informasi/pengalaman dan merupakan personalisasi. Pembuatan sepatu mengubah produk sehingga merupakan customization. Keduanya dapat digabung, tetapi objek yang diubah berbeda.');
tf(3,'Online brokerage','s7','Aplikasi trading yang mengirim order secara elektronik masih dapat memerlukan broker serta bursa untuk memproses transaksi.',true,'Antarmuka elektronik mendigitalkan akses, bukan otomatis menghilangkan seluruh lembaga perantara. Diagram materi menempatkan sistem broker dan koneksi ke bursa di belakang antarmuka pengguna.');
tf(3,'Flash sales dan kanal','s3','Karena flash sale membatasi waktu penawaran, retailer yang memakainya tidak lagi dapat diklasifikasikan click-and-mortar.',false,'Flash sale adalah mekanisme promosi/penjualan; click-and-mortar adalah struktur kanal. Satu retailer dapat menggabungkan keduanya. Memilih satu tidak meniadakan sumbu yang lain.');

mc(4,'Sumbu klasifikasi B2B','s2','Pabrik membeli pelumas untuk pemeliharaan mesin melalui kontrak tahunan dengan distributor khusus industri. Klasifikasi tujuan barang dan pola pembelian adalah…','Pelumas yang dipakai merawat mesin tidak masuk langsung ke produk akhir, sehingga termasuk MRO/indirect dalam konteks ini. Kontrak tahunan menunjukkan systematic sourcing. Sektor pemasok merupakan sumbu lain.',[
 ['Indirect/MRO; systematic sourcing','Tujuan pemeliharaan dan hubungan kontraktual mendukung dua label ini.'],['Direct material; spot purchasing','Barang tidak menjadi komponen produk dan pembelian tidak insidental.'],['Indirect/MRO; spot purchasing','Tujuan barang benar, tetapi kontrak tahunan menunjukkan pola terencana.'],['Direct material; systematic sourcing','Pola kontrak benar, tetapi tujuan penggunaan bukan bahan langsung.']]);
mc(4,'E-tendering vs reverse auction','s7','Universitas mengundang proposal implementasi sistem dengan pendekatan teknis berbeda. Evaluasi mencakup integrasi, layanan dan biaya. Menjadikan harga terendah satu-satunya dasar pemenang terutama bermasalah karena…','Reverse auction paling jelas ketika penawaran dapat dibandingkan terhadap spesifikasi yang setara. Dalam kasus solusi heterogen, harga tidak mewakili seluruh nilai atau risiko. Tender elektronik dapat memakai evaluasi multikriteria tanpa lelang berulang.',[
 ['Solusi belum setara pada dimensi yang dinilai','Perbedaan kualitas/pendekatan memerlukan evaluasi sebelum membandingkan harga.'],['Proposal elektronik selalu tidak dapat diaudit','Kanal elektronik tidak otomatis menghilangkan auditabilitas.'],['Pembeli institusi tidak boleh menilai harga','Harga tetap relevan, hanya tidak cukup sebagai satu-satunya kriteria.'],['Reverse auction membutuhkan banyak pembeli','Strukturnya justru satu pembeli mengundang banyak pemasok.']]);
mc(4,'Total cost of ownership','s6','Vendor A menawarkan Rp90 juta dengan operasi tahunan Rp25 juta. Vendor B menawarkan Rp110 juta dengan operasi Rp15 juta. Untuk tiga tahun tanpa diskonto/nilai sisa, pilihan berbasis total biaya adalah…','Hitung komponen pada horizon yang sama. A = 90 + 3×25 = 165 juta; B = 110 + 3×15 = 155 juta. Harga awal yang lebih murah tidak menjamin total biaya lebih rendah.',[
 ['B lebih rendah Rp10 juta selama tiga tahun','Selisih biaya awal tertutup oleh penghematan operasi tiga tahun.'],['A lebih rendah Rp20 juta selama tiga tahun','Ini selisih harga awal yang mengabaikan biaya operasi.'],['A lebih rendah Rp10 juta selama tiga tahun','A justru memiliki total biaya Rp10 juta lebih tinggi.'],['B lebih rendah Rp30 juta selama tiga tahun','Ini penghematan operasi sebelum mengurangi tambahan harga awal B.']]);
mc(4,'Desktop vs maverick purchasing','s8','Pegawai memesan alat tulis dari katalog kontrak memakai batas anggaran otomatis. Pegawai lain membeli item sama dari situs luar tanpa persetujuan. Pasangan paling tepat adalah…','Desktop purchasing dapat mendesentralisasikan order sambil mempertahankan kontrol kontrak. Maverick purchasing melewati ketentuan pengadaan. Kedua aktivitas dilakukan individu, tetapi tingkat kepatuhannya berbeda.',[
 ['Desktop purchasing; maverick purchasing','Yang pertama terkendali katalog/anggaran; yang kedua melewati prosedur.'],['Maverick purchasing; desktop purchasing','Membalik arti kontrol proses yang dijelaskan dalam kasus.'],['Strategic sourcing; group purchasing','Kasus membahas pelaksanaan order, bukan pemilihan strategi atau agregasi.'],['Reverse auction; forward auction','Tidak ada kompetisi bid pada kedua pembelian tersebut.']]);
mc(4,'Vertical vs horizontal exchange','s9','Platform mempertemukan perusahaan dari banyak industri untuk membeli perlengkapan kantor. Karakter pasar utamanya adalah…','Horizontal menjangkau kebutuhan lintas industri, sering untuk input umum seperti MRO. Vertical melayani rantai atau kebutuhan industri tertentu. Jenis barang dan cakupan industri perlu dibedakan dari kepemilikan platform.',[
 ['Horizontal exchange untuk kebutuhan lintas industri','Perlengkapan umum digunakan oleh pembeli dari berbagai sektor.'],['Vertical exchange karena pembelinya perusahaan','Status pembeli bisnis tidak menjadikan pasar khusus satu industri.'],['Private sell-side karena barangnya terstandar','Standarisasi barang tidak menentukan kepemilikan satu penjual.'],['Buy-side tunggal karena kebutuhan pembeli serupa','Kesamaan kebutuhan tidak berarti hanya ada satu pembeli.']]);
mc(4,'Buying center','s1','Dalam pengadaan laptop, laboratorium menyusun spesifikasi, unit pengadaan menegosiasi kontrak, dan pimpinan menyetujui pilihan. Pasangan peran lab dan unit pengadaan adalah…','Peran buying center ditentukan aktivitas. Lab memengaruhi kriteria teknis; unit pengadaan menangani sourcing/negosiasi. Otoritas keputusan akhir pada pimpinan berbeda dari dua peran tersebut.',[
 ['Influencer dan buyer','Spesifikasi memengaruhi pilihan; negosiasi/pengadaan merupakan fungsi buyer.'],['Decider dan gatekeeper','Kasus menempatkan keputusan final pada pimpinan dan tidak menyebut pengendalian akses.'],['Gatekeeper dan user','Kedua kegiatan yang disebut bukan pembatasan informasi atau penggunaan akhir.'],['Buyer dan decider','Menyusun spesifikasi bukan otomatis membeli; negosiasi bukan persetujuan final.']]);
mc(4,'Collaborative commerce','s11','Pemasok dan produsen berbagi forecast serta menyelaraskan rencana produksi sebelum ada order pembelian. Nilai utama aktivitas tersebut adalah…','Kolaborasi mengoordinasikan keputusan lintas perusahaan, bukan hanya mengeksekusi transaksi. Berbagi rencana dapat memperbaiki keselarasan pasokan-permintaan. Belum adanya PO tidak membuat kegiatan tersebut berada di luar c-commerce.',[
 ['Menyelaraskan rencana permintaan dan pasokan','Koordinasi dilakukan sebelum transaksi untuk memperbaiki operasi bersama.'],['Mengubah seluruh transaksi menjadi C2C','Tidak ada perubahan identitas pelaku dari bisnis ke individu.'],['Menaikkan komisi marketplace per pesanan','Kasus tidak menyebut perantara atau model komisi.'],['Memindahkan kendali mutu kepada konsumen','Aktivitas berfokus pada rencana organisasi, bukan pelimpahan mutu.']]);
tf(4,'EDI dan B2B','s1','Perusahaan dapat menjalankan B2B tanpa EDI, dan penggunaan EDI menunjukkan mekanisme pertukaran dokumen, bukan dengan sendirinya model pendapatan.',true,'B2B mengklasifikasikan hubungan organisasi. EDI merupakan salah satu cara dokumen terstruktur dipertukarkan. Model pendapatan tetap perlu dijelaskan terpisah dari sarana komunikasi.');
tf(4,'Group purchasing','s8','Jika jumlah anggota kelompok bertambah tetapi total unit yang dipesan tidak bertambah, daya tawar berbasis volume otomatis meningkat dengan proporsi yang sama.',false,'Daya tawar volume mengikuti permintaan/komitmen ekonomis yang digabung, bukan jumlah anggota saja. Frekuensi, kepastian, biaya pelayanan dan syarat pemasok juga menentukan manfaat.');
tf(4,'Supply chain dan sistem','s10','CRM berfokus pada hubungan pelanggan dan SRM pada pemasok; keduanya dapat berkontribusi pada koordinasi rantai pasok meskipun objek hubungannya berbeda.',true,'Hubungan pelanggan menyediakan sinyal kebutuhan, sementara pemasok menyediakan kemampuan pasokan. Integrasi informasi membantu koordinasi tanpa menjadikan CRM dan SRM sinonim.');

mc(5,'Kategori e-government','s3','Dinas A dan dinas B bertukar data untuk mempercepat verifikasi bantuan. Portal yang sama juga menyediakan penggajian pegawai. Dua fungsi tersebut paling tepat dipetakan sebagai…','Klasifikasi ditentukan relasi pada fungsi tertentu. Pertukaran antardinas merupakan G2G; layanan langsung kepada pegawai merupakan G2E dan dapat meningkatkan IEE. Satu portal tidak wajib memiliki satu kategori tunggal.',[
 ['G2G; G2E dengan manfaat IEE','Membedakan relasi antarlembaga dan pemerintah-pegawai.'],['G2C; G2B dengan manfaat IEE','Data verifikasi ditukar antardinas, bukan langsung dengan warga/bisnis.'],['G2E; G2G dengan manfaat G2C','Pertukaran antarinstansi bukan layanan pegawai; penggajian bukan antarinstansi.'],['G2B; G2C dengan manfaat G2E','Tidak ada bisnis pada fungsi pertama atau warga umum pada fungsi kedua.']]);
mc(5,'E-voting','s3','Sistem e-voting menghitung suara cepat dan melakukan autentikasi pemilih. Namun tidak tersedia bukti untuk memeriksa ulang hasil penghitungan. Penilaian yang paling tepat adalah…','Autentikasi dan kecepatan tidak menjamin integritas hasil dapat diverifikasi. Materi menekankan keamanan serta audit. Ketiadaan audit trail yang memadai menyisakan pertanyaan tentang pemeriksaan hasil, bukan membuktikan hasil pasti salah.',[
 ['Kemampuan audit hasil belum memadai','Kasus menunjukkan kekurangan verifikasi ulang meski autentikasi tersedia.'],['Identitas semua pemilih pasti tidak valid','Tidak ada bukti autentikasi yang dilakukan gagal memverifikasi identitas.'],['Kecepatan hitung membuktikan integritas suara','Kecepatan adalah dimensi performa, bukan bukti kebenaran hasil.'],['Digitalisasi sudah memenuhi seluruh kriteria','Keberadaan sistem elektronik tidak mencukupi semua tujuan keamanan/audit.']]);
mc(5,'LMS vs KM','s4','Universitas ingin mengelola jadwal, penugasan, nilai dan akses modul. Perusahaan mitranya ingin menyimpan solusi teknisi, menemukan pakar dan memakai ulang praktik kerja. Pasangan sistem dominan adalah…','LMS mengelola proses pembelajaran, sedangkan KM mengelola pengetahuan organisasi. Kedua sistem dapat berbagi konten, tetapi fungsi dominan kasus berbeda. E-learning juga dapat memperbaiki operasi secara tidak langsung.',[
 ['LMS untuk universitas; KM untuk perusahaan','Administrasi belajar berbeda dari repositori/pencarian kepakaran organisasi.'],['KM untuk universitas; LMS untuk perusahaan','Membalik fungsi dominan yang diminta kedua organisasi.'],['ELS untuk universitas; e-reader untuk perusahaan','Pencarian pakar bukan pengelolaan nilai; pembaca buku bukan sistem KM.'],['Portal pembayaran untuk keduanya','Tidak ada kebutuhan pembayaran utama dalam dua uraian tersebut.']]);
mc(5,'Knowledge refinement','s5','Tim mengambil solusi forum, menguji pada tiga konfigurasi, lalu menambahkan kondisi kapan solusi gagal. Tahap KM yang paling dominan adalah…','Aktivitas utama adalah memvalidasi serta memberi konteks agar pengetahuan dapat diterapkan dengan tepat. Sumbernya forum tidak menentukan tahap. Ini refinement, meskipun dapat didahului capture dan diikuti dissemination.',[
 ['Refine: memvalidasi dan memberi konteks','Pengujian serta batas penerapan merupakan inti refinement.'],['Capture: mencatat pengalaman yang tersedia','Pengambilan awal ada, tetapi kasus menekankan validasi berikutnya.'],['Store: mengarsipkan dokumen ke repositori','Tidak menjelaskan pengujian dan penambahan syarat penerapan.'],['Disseminate: menyalurkan hasil ke pengguna','Belum ada tindakan distribusi sebagai fokus utama kasus.']]);
mc(5,'Expert location system','s5','Pertanyaan tidak memiliki jawaban cocok dalam repositori. Sistem menemukan teknisi yang relevan dan meminta solusi. Agar pembelajaran organisasi berlanjut, langkah setelah solusi tersedia sebaiknya…','ELS tidak hanya menghubungkan orang. Solusi perlu ditinjau, disampaikan dan ditambahkan ke repositori agar kasus serupa tidak selalu mengulang pencarian pakar. Validasi menjaga kualitas pengetahuan yang dibagikan.',[
 ['Tinjau solusi, kirim, dan perbarui repositori','Menyelesaikan kebutuhan sekarang sekaligus membangun pengetahuan reusable.'],['Kirim solusi lalu hapus jejak pertanyaannya','Menjawab kebutuhan sesaat, tetapi kehilangan kesempatan penggunaan ulang.'],['Ubah pertanyaan agar selalu cocok dengan FAQ','Memaksakan kecocokan tanpa menjamin jawaban relevan terhadap masalah.'],['Ganti pakar dengan voting tanpa peninjauan','Popularitas jawaban tidak menggantikan pemeriksaan akurasi.']]);
mc(5,'E-health sebagai sistem','s6','Rumah sakit menghubungkan hasil laboratorium ke catatan pasien dan memberi dokter akses berdasarkan peran. Nilai utama dan batas yang paling tepat adalah…','Integrasi mendukung koordinasi dan akses informasi pasien. Hak akses tetap perlu dibatasi; ketersediaan data tidak berarti semua orang boleh melihatnya. E-health mencakup informasi dan operasi selain transaksi obat.',[
 ['Koordinasi layanan meningkat; akses tetap terkendali','Menggabungkan manfaat integrasi dengan kebutuhan otorisasi.'],['Transaksi obat meningkat; semua akses diseragamkan','Kasus tidak berfokus pada penjualan dan tidak membenarkan akses identik.'],['Perantara dihapus; pemeriksaan klinis digantikan','Integrasi catatan tidak berarti tenaga/proses klinis menjadi tidak perlu.'],['Akurasi diagnosis terjamin; data dapat dibuka','Sistem informasi tidak menjamin diagnosis atau menghapus privasi.']]);
mc(5,'C2C dan platform','s7','Dua individu bertransaksi barang bekas lewat platform yang menyediakan escrow dan mengenakan biaya layanan. Relasi barang dan layanan platform paling tepat dibedakan sebagai…','Barang tetap dipertukarkan antarindividu, sehingga C2C. Platform menyediakan layanan bisnis yang dapat dibedakan dari relasi barang. Klasifikasi tidak berubah hanya karena pembayaran melalui perantara.',[
 ['C2C pada barang; layanan bisnis oleh platform','Memisahkan hubungan transaksi inti dan layanan fasilitasi.'],['B2B pada barang; intrabusiness oleh platform','Individu tidak berubah menjadi organisasi karena memakai escrow.'],['B2C pada barang; C2C pada biaya platform','Platform tidak dinyatakan memiliki barang; biaya berasal dari layanan bisnis.'],['G2C pada barang; B2E pada biaya platform','Tidak ada pemerintah atau hubungan pemberi kerja dalam kasus.']]);
tf(5,'M-government','s3','Peringatan bencana dari pemerintah ke ponsel warga dapat sekaligus diklasifikasikan G2C dan m-government.',true,'G2C menyebut relasi pelakunya, sedangkan m-government menyebut penggunaan kanal/platform mobile. Dua dimensi tersebut dapat berlaku sekaligus pada satu layanan.');
tf(5,'E-learning dan hasil','s4','Selesainya seluruh video LMS belum cukup membuktikan peserta mampu menerapkan prosedur kerja yang diajarkan.',true,'Penyelesaian konten mengukur aktivitas belajar. Penguasaan memerlukan asesmen/praktik sesuai kompetensi dan bukti penerapan. LMS dapat mendukung pengukuran tersebut, tetapi metrik tontonan bukan penggantinya.');
tf(5,'E-books dan perangkat','s4','Karena e-book berupa konten digital, semua e-reader pasti mendukung video, warna, dan pembaruan online dengan cara yang sama.',false,'Kemampuan bergantung format, perangkat dan software. E-book adalah konten; e-reader adalah alat. Menyamakan semua perangkat menggeneralisasikan fitur yang hanya tersedia pada sebagian implementasi.');

mc(6,'Atribut mobile','s2','Dua orang di lokasi dan waktu yang sama membuka aplikasi. Urutan penawaran berbeda karena riwayat minat masing-masing. Atribut yang paling langsung ditunjukkan adalah…','Lokasi dan waktu sengaja dibuat sama agar pembeda yang diuji adalah penyesuaian individu. Ini personalization. Ubiquity, convenience dan interactivity bisa hadir, tetapi tidak menjelaskan variasi urutan berdasarkan minat.',[
 ['Personalization berdasarkan profil pengguna','Perbedaan isi ditentukan preferensi masing-masing individu.'],['Localization berdasarkan koordinat pengguna','Koordinat sama sehingga tidak menjelaskan perbedaan yang dinyatakan.'],['Ubiquity berdasarkan akses lintas tempat','Kasus tidak membandingkan kemampuan akses di lokasi berbeda.'],['Interactivity berdasarkan komunikasi dua arah','Tidak ada percakapan atau pertukaran respons yang diuji.']]);
mc(6,'Fondasi dan kemampuan tambahan','s3','Toko mobile berjalan dengan katalog, order, pembayaran dan jaringan nirkabel. Tim ingin menambahkan rekomendasi berbasis AI. Kesimpulan yang tepat adalah…','EC mobile sudah terjadi tanpa rekomendasi AI. Sistem cerdas dapat menambah relevansi, tetapi bukan syarat definisional agar transaksi mobile berlangsung. Prasyarat layanan dasar harus dipisahkan dari peningkatan kemampuan.',[
 ['AI memperkaya layanan yang telah berfungsi','Kasus membuktikan transaksi sudah dapat berlangsung sebelum AI.'],['Tanpa AI transaksi tadi masih bukan m-commerce','M-commerce tidak ditentukan oleh keberadaan intelligent systems.'],['AI menggantikan kebutuhan jaringan nirkabel','Pemrosesan rekomendasi tidak meniadakan kanal komunikasi layanan.'],['AI mengubah pembeli menjadi pihak B2B','Teknologi tidak mengubah identitas atau tujuan pelaku transaksi.']]);
mc(6,'Mapping, navigation, tracking','s5','Aplikasi menampilkan titik-titik toko, memberi instruksi belok menuju toko terpilih, lalu memperbarui posisi kurir. Tiga fungsi dominannya berturut-turut adalah…','Representasi tempat, panduan perjalanan, dan pemantauan pergerakan adalah fungsi yang berbeda. Ketiganya dapat memakai peta yang sama. Penentuan kategori harus mengikuti aktivitas, bukan tampilan peta semata.',[
 ['Mapping; navigation; tracking','Titik lokasi, panduan rute, dan pemantauan posisi sesuai urutan kasus.'],['Navigation; tracking; mapping','Titik toko tidak memandu perjalanan; urutan dua fungsi lain juga tertukar.'],['Tracking; mapping; navigation','Posisi toko statis bukan pelacakan; kurir bergerak bukan instruksi belok.'],['Mapping; tracking; navigation','Dua fungsi terakhir dibalik: petunjuk arah berbeda dari pemantauan.']]);
mc(6,'Alur LBS','s4','Koordinat pengguna akurat, tetapi aplikasi merekomendasikan toko yang sudah tutup karena data jam operasional lama. Komponen yang paling langsung perlu diperbaiki adalah…','Akurasi posisi bukan satu-satunya syarat relevansi layanan lokasi. Kasus menunjukkan data bisnis yang dipakai untuk menafsirkan koordinat sudah basi. Sensor baru tidak memperbarui informasi jam operasional.',[
 ['Pemeliharaan data tempat dan aturan rekomendasi','Menangani sumber kesalahan jam operasional serta pemilihan hasil.'],['Presisi sensor lokasi pada perangkat pengguna','Posisi sudah dinyatakan akurat sehingga bukan bukti masalah utama.'],['Kapasitas baterai pada perangkat bergerak','Daya perangkat tidak menjelaskan data jam toko yang usang.'],['Format pembayaran pada aplikasi merchant','Tidak terkait dengan penentuan toko yang sedang buka.']]);
mc(6,'Context-aware computing','s5','Aplikasi menunda notifikasi promosi saat pengguna berada dalam sesi kuliah yang tercantum di kalender. GPS tidak digunakan. Penilaian yang tepat adalah…','Konteks dapat berupa waktu dan aktivitas. Lokasi merupakan satu jenis konteks, bukan prasyarat seluruh context-aware computing. Fungsi ini memakai informasi situasi untuk menyesuaikan perilaku layanan.',[
 ['Context-aware berbasis waktu dan aktivitas','Penyesuaian menggunakan situasi pengguna yang relevan.'],['LBS berbasis koordinat dari jadwal kalender','Kalender tidak dengan sendirinya menyediakan koordinat lokasi.'],['Mapping berbasis kategori mata kuliah','Tidak ada representasi geografis dalam kegiatan yang dijelaskan.'],['Tracking berbasis perpindahan antarjaringan','Kasus tidak memantau gerakan atau perpindahan jaringan.']]);
mc(6,'Bandwidth dan respons','s7','Kapasitas koneksi digandakan, tetapi respons checkout tetap lambat. Pengukuran menunjukkan server membutuhkan empat detik memproses setiap order. Langkah paling relevan adalah…','Kapasitas transfer bukan satu-satunya komponen waktu respons. Bukti kasus menunjuk pemrosesan server sebagai hambatan. Bandwidth tambahan dapat berguna untuk transfer, tetapi tidak otomatis mengurangi waktu komputasi backend.',[
 ['Perbaiki pemrosesan order di sisi backend','Mengikuti hasil pengukuran sumber waktu tunggu dominan.'],['Gandakan bandwidth untuk menghapus semua latensi','Kapasitas lebih besar tidak menghapus waktu proses server.'],['Kurangi presisi GPS untuk mempercepat order','Tidak ada bukti lokasi menjadi hambatan checkout.'],['Tambah animasi agar pemrosesan lebih singkat','Tampilan tidak memperpendek kerja server secara langsung.']]);
mc(6,'IoT dan nilai proses','s6','Sensor gudang mengirim suhu setiap menit, tetapi tidak ada alarm atau tindakan ketika batas terlewati. Tambahan yang paling langsung mengubah data menjadi nilai operasi adalah…','Penginderaan dan transmisi belum menyelesaikan masalah bisnis. Aturan, notifikasi yang tepat, pemilik tindakan dan pencatatan respons membentuk loop keputusan. Lebih banyak data tidak membantu jika tidak digunakan.',[
 ['Aturan ambang, eskalasi, dan prosedur respons','Menghubungkan pembacaan sensor dengan keputusan serta tindakan.'],['Frekuensi unggah dan jumlah dashboard tambahan','Menambah visibilitas tanpa memastikan tindak lanjut terhadap masalah.'],['Tema antarmuka dan ukuran grafik lebih besar','Mengubah presentasi, bukan logika penanganan kejadian.'],['Jumlah perangkat dan panjang arsip diperbanyak','Menaikkan volume data tanpa menutup celah respons.']]);
tf(6,'Kompleksitas fitur','s7','Menambahkan fitur mobile dapat meningkatkan cakupan tugas sekaligus meningkatkan beban belajar; kedua dampak itu tidak saling meniadakan.',true,'Manfaat fungsional dan kompleksitas adalah dimensi berbeda. Desain perlu mempertimbangkan kebutuhan pengguna, konteks dan prioritas tugas. Lebih banyak fitur tidak otomatis lebih baik atau lebih buruk.');
tf(6,'IoT dan M2M','s6','Komunikasi dua mesin pada jaringan lokal sudah cukup membuktikan bahwa tersedia layanan IoT end-to-end lengkap bagi pengguna.',false,'M2M merupakan mekanisme komunikasi. Layanan IoT end-to-end dapat memerlukan pengelolaan perangkat, pengolahan data, aplikasi, kontrol dan integrasi. Bukti komunikasi saja tidak memastikan keseluruhan arsitektur.');
tf(6,'Manfaat potensial','s2','Fitur informasi real-time dapat membantu keputusan belanja, tetapi tanpa data akurat fitur itu belum menjamin kepuasan konsumen meningkat.',true,'Ketepatan waktu berbeda dari ketepatan isi. Informasi cepat yang salah justru dapat menghasilkan keputusan buruk. Karena itu manfaat harus dievaluasi bersama kualitas data dan hasil yang relevan bagi pengguna.');

mc(7,'Group buying','s3','Kelompok A memiliki 80 anggota dengan total komitmen 80 unit. Kelompok B memiliki 8 anggota dengan total komitmen 400 unit. Pemasok memberi diskon menurut volume pasti, dengan biaya distribusi sama. Dasar tawar yang lebih kuat adalah…','Kasus menetapkan volume pasti sebagai dasar diskon dan menyamakan biaya distribusi. Kelompok B menggabungkan permintaan lebih besar walau anggotanya lebih sedikit. Jangan mengganti jumlah unit dengan jumlah akun.',[
 ['Kelompok B karena komitmen unit lebih besar','Sesuai variabel yang dipakai pemasok pada kondisi kasus.'],['Kelompok A karena jumlah anggota lebih banyak','Jumlah anggota tidak sama dengan volume pembelian.'],['Keduanya sama karena memakai group buying','Nama mekanisme tidak membuat skala permintaan identik.'],['Kelompok A karena permintaan lebih tersebar','Sebaran tidak dinyatakan sebagai kriteria diskon dan biaya disamakan.']]);
mc(7,'Taxonomy vs folksonomy','s5','Pegawai memberi tag bebas pada dokumen, lalu pengelola memetakan sinonim ke kategori resmi. Interpretasi paling tepat adalah…','Kontribusi tag berasal dari pengguna, sedangkan pemetaan resmi merupakan kurasi terstruktur. Enterprise 2.0 tidak menuntut penghapusan seluruh kontrol. Kedua pola dapat dipadukan untuk partisipasi dan kemudahan penemuan.',[
 ['Folksonomy dikombinasikan dengan taxonomy','Tag emergen dan kategori terkelola hadir bersama.'],['Taxonomy murni tanpa kontribusi pengguna','Mengabaikan tag bebas yang dibuat pegawai.'],['Folksonomy murni tanpa pengelolaan kategori','Mengabaikan pemetaan resmi yang dilakukan pengelola.'],['Personalisasi menggantikan klasifikasi dokumen','Tidak ada penyesuaian isi per individu sebagai fokus kasus.']]);
mc(7,'Data management vs analytics','s4','Tim A menghapus ulasan duplikat dan memperbaiki format tanggal. Tim B menguji hubungan sentimen dengan retur. Tim C menampilkan hasil mingguan. Urutan fungsi dominan adalah…','Pembersihan memperbaiki kualitas data; pengujian hubungan menafsirkan data; penyajian hasil merupakan reporting. Fungsi dapat terintegrasi dalam sistem yang sama tanpa menjadikan istilahnya sinonim.',[
 ['Data management; analytics; reporting','Membedakan kualitas data, interpretasi, dan penyajian hasil.'],['Analytics; reporting; data management','Pembersihan bukan pengujian pola; grafik bukan pengelolaan format.'],['Reporting; data management; analytics','Menukar tujuan utama ketiga aktivitas yang dijelaskan.'],['Personalization; analytics; crowdsourcing','Tidak ada penyesuaian pengguna atau pengumpulan tugas crowd.']]);
mc(7,'Kualitas UGC','s4','Produk P memiliki rating 4,9 dari 8 ulasan; Q memiliki 4,7 dari 2.000 ulasan. Distribusi pengguna dan verifikasi pembelian belum diketahui. Kesimpulan paling hati-hati adalah…','Rata-rata dan ukuran sampel belum menjelaskan bias, keterwakilan, verifikasi serta kecocokan kebutuhan. Data lebih banyak dapat meningkatkan stabilitas tertentu, tetapi tidak otomatis menghapus bias. Tidak sah memastikan produk terbaik hanya dari dua angka ini.',[
 ['Perlu konteks ulasan sebelum memastikan pilihan','Memerlukan kualitas bukti dan relevansi pengguna, bukan rata-rata saja.'],['P pasti lebih baik karena rata-ratanya tinggi','Mengabaikan ukuran, variasi, dan kualitas sampel.'],['Q pasti lebih baik karena ulasannya banyak','Jumlah besar tidak menjamin kecocokan atau ketiadaan bias.'],['Keduanya setara karena beda ratingnya kecil','Kesetaraan tidak dapat dipastikan tanpa distribusi dan konteks.']]);
mc(7,'Hambatan adopsi','s7','Pegawai antusias memakai jejaring internal dan integrasi teknis sudah berhasil. Direksi menunda perluasan karena manfaat finansial belum dapat dibuktikan dibanding biaya. Hambatan dominan adalah…','Kasus menyingkirkan resistensi pengguna dan kegagalan integrasi. Masalahnya justifikasi nilai investasi. Pilot dengan baseline, biaya dan ukuran hasil relevan lebih tepat daripada sekadar pelatihan ulang antarmuka.',[
 ['Justifikasi imbal balik investasi','Direksi mempertanyakan manfaat relatif terhadap biaya.'],['Resistensi pegawai terhadap perubahan','Kasus menyatakan pegawai antusias, sehingga bukan bukti utama.'],['Integrasi sistem lama dengan sistem baru','Integrasi sudah dinyatakan berhasil.'],['Keterbatasan jaringan pada perangkat kerja','Tidak ada bukti kendala jaringan yang menunda keputusan.']]);
mc(7,'ROI dan manfaat','s7','Biaya pilot jejaring pengetahuan Rp120 juta. Estimasi penghematan tervalidasi Rp150 juta pada periode yang sama. ROI sederhana dan batas interpretasinya adalah…','ROI = (150−120)/120 = 25%. Validasi manfaat dan kesamaan periode membuat perhitungan bermakna dalam asumsi kasus. Hasil itu belum otomatis berlaku bagi skala lebih besar dengan struktur biaya berbeda.',[
 ['25%; perlu uji ulang ketika skala berubah','Perhitungan benar dan tidak menggeneralisasikan di luar asumsi.'],['125%; berlaku tetap pada semua skala','125% adalah manfaat/biaya, bukan pengembalian bersih; klaim tetap juga berlebihan.'],['20%; dapat mengabaikan baseline manfaat','20% memakai manfaat sebagai denominator dan mengabaikan dasar pembanding.'],['30%; cukup berdasarkan banyaknya posting','30 adalah selisih juta, bukan persentase; posting bukan manfaat finansial.']]);
mc(7,'Social shopping aids','s2','Pembeli menyimpan tautan produk, membagikannya ke teman, lalu menerima saran. Fungsi yang paling langsung menggambarkan tindakan menyimpan dan berbagi tautan adalah…','Social bookmarking menyusun serta membagikan rujukan. Referral program memerlukan mekanisme rujukan/insentif tertentu, sedangkan sponsored review menyangkut hubungan pembuat konten dan sponsor. Tidak semua berbagi tautan otomatis afiliasi.',[
 ['Social bookmarking','Menyimpan dan membagikan rujukan sesuai fungsi yang dijelaskan.'],['Sponsored review','Kasus tidak menyebut ulasan berbayar atau hubungan sponsor.'],['Reverse auction','Tidak ada persaingan pemasok untuk kebutuhan pembeli.'],['Electronic benefits transfer','Ini distribusi manfaat pemerintah, bukan mekanisme rujukan belanja.']]);
tf(7,'KM dan komunitas','s6','Forum yang menguji solusi, mengoreksi kesalahan, dan memberi batas penggunaan dapat melakukan knowledge refinement meskipun sumber ide awalnya juga forum.',true,'Tahap KM mengikuti kegiatan. Menguji dan memberi konteks merupakan refinement, sedangkan melahirkan ide adalah creation. Platform yang sama dapat mendukung banyak tahap siklus.');
tf(7,'Social commerce dan multimedia','s2','Video produk yang sama bagi semua pengunjung pasti merupakan personalisasi karena formatnya lebih kaya daripada teks.',false,'Multimedia merujuk format penyajian, sedangkan personalisasi menyesuaikan pengalaman terhadap individu. Video yang sama dapat kaya informasi tanpa bersifat personal.');
tf(7,'Indikator aktivitas','s7','Jumlah posting yang naik dapat menjadi indikator partisipasi, tetapi belum cukup untuk menyimpulkan jejaring perusahaan meningkatkan laba.',true,'Posting mengukur aktivitas. Hubungan ke laba memerlukan jalur manfaat, biaya dan bukti hasil. Penilaian dapat memakai metrik antara, tetapi tidak boleh langsung menyamakan aktivitas dengan keuntungan.');

mc(8,'Authentication vs authorization','s4','Pegawai berhasil login menggunakan MFA, tetapi masih dapat mengubah rekening pemasok di luar kewenangannya. Kontrol yang paling langsung kurang adalah…','MFA meningkatkan bukti identitas, bukan pembatasan tindakan setelah login. Kasus menunjukkan kegagalan otorisasi. Sistem perlu menentukan hak perubahan data sensitif sesuai peran dan proses persetujuan.',[
 ['Authorization atas perubahan rekening pemasok','Membatasi operasi yang diizinkan setelah identitas diverifikasi.'],['Authentication atas identitas pegawai tersebut','Autentikasi sudah berhasil; bukti masalahnya hak akses.'],['Compression atas dokumen pemasok tersimpan','Ukuran data tidak menentukan izin perubahan.'],['Personalization atas urutan menu pegawai','Menyembunyikan/menu personal bukan penegakan hak pada backend.']]);
mc(8,'Payment lifecycle','s5','Issuer menyetujui transaksi kartu. Merchant belum melakukan capture dan dana belum diterima. Pernyataan yang paling tepat adalah…','Authorization merupakan keputusan persetujuan, bukan settlement. Capture dan proses clearing/settlement berikutnya masih diperlukan sesuai mekanisme jaringan. Tampilan disetujui tidak membuktikan penerimaan dana merchant.',[
 ['Otorisasi selesai; settlement belum terbukti','Membedakan keputusan issuer dari penyelesaian dana.'],['Settlement selesai; otorisasi menunggu capture','Membalik dependensi dan menganggap dana sudah selesai.'],['Capture selesai; clearing berarti verifikasi login','Kasus menyatakan capture belum dilakukan; clearing bukan login.'],['Semua tahap selesai; dana hanya belum terlihat','Tidak ada bukti seluruh tahap sudah terjadi.']]);
mc(8,'CTR dan CPM','s3','Kampanye menghabiskan Rp900.000 untuk 150.000 tayangan dan 3.000 klik. Pasangan CTR dan CPM yang benar adalah…','CTR = 3.000/150.000 = 2%. CPM = 900.000/150.000×1.000 = Rp6.000. CTR menggunakan klik sebagai numerator; CPM mengukur biaya per seribu tayangan.',[
 ['2% dan Rp6.000','Kedua denominator mengikuti definisi yang tepat.'],['2% dan Rp300','Rp300 adalah biaya per klik, bukan biaya per seribu tayangan.'],['5% dan Rp6.000','CPM benar, tetapi perhitungan CTR tidak sesuai 3.000/150.000.'],['50% dan Rp300','Menggunakan rasio yang keliru dan menukar CPM dengan CPC.']]);
mc(8,'Threat vs vulnerability','s4','Prosedur pemberian akses tidak pernah ditinjau, sehingga akun mantan pegawai masih aktif. Penyerang kemudian memakainya untuk mengambil data. Pasangan kondisi dan kejadian adalah…','Akun yang masih dapat digunakan serta prosedur usang merupakan kelemahan. Pengambilan data oleh penyerang merupakan tindakan/insiden yang memanfaatkannya. Klasifikasi ini membantu memilih kontrol yang sesuai akar masalah.',[
 ['Vulnerability; tindakan ancaman yang terealisasi','Kelemahan akses berbeda dari kejadian penyalahgunaan.'],['Authentication; pemulihan ketersediaan sistem','Kasus bukan definisi verifikasi identitas atau recovery.'],['Deterrence; penguatan integritas informasi','Prosedur usang tidak menjadi kontrol penjeraan dan data diambil.'],['Settlement; kegagalan personalisasi layanan','Konsep pembayaran/personalization tidak menjelaskan peristiwa keamanan.']]);
mc(8,'Balanced scorecard','s8','Tujuan perusahaan adalah mempercepat order-to-delivery. KPI “median waktu picking gudang” paling langsung berada pada perspektif…','Picking adalah bagian proses operasi internal. Dampaknya dapat menjalar ke kepuasan dan keuangan, tetapi objek ukuran tetap proses. Perspektif dibedakan dari dampak akhirnya agar scorecard tidak mencampur semua metrik.',[
 ['Proses bisnis internal','Ukuran langsung mengamati kecepatan kegiatan operasional.'],['Keuangan perusahaan','Tidak mengukur pendapatan, margin atau pengembalian.'],['Pelanggan dan pasar','Tidak secara langsung mengukur persepsi atau perilaku pelanggan.'],['Pembelajaran dan pertumbuhan','Tidak mengukur kemampuan/kompetensi yang mendukung proses.']]);
mc(8,'Magic Quadrant','s8','Dalam evaluasi suatu pasar, vendor dinilai memiliki visi arah pasar kuat tetapi kemampuan eksekusi relatif tertinggal. Kategori yang dituju adalah…','Sumbu visi dan eksekusi perlu dibaca terpisah. Visionaries kuat pada visi relatif terhadap eksekusi. Kategori tidak otomatis menentukan vendor terbaik bagi semua kebutuhan; evaluasi tetap kontekstual.',[
 ['Visionaries','Cocok dengan visi kuat dan eksekusi yang belum setara.'],['Challengers','Kategori ini relatif kuat pada eksekusi, bukan pasangan dalam kasus.'],['Leaders','Memerlukan kekuatan pada kedua dimensi yang dinilai.'],['Niche Players','Bukan label spesifik bagi kombinasi visi kuat-eksekusi tertinggal.']]);
mc(8,'Markup vs margin','s6','Biaya produk Rp80.000. Perusahaan menetapkan markup 25% dari biaya. Harga jual dan margin terhadap harga jual adalah…','Markup biaya = 25%×80.000 = 20.000, sehingga harga 100.000. Margin = 20.000/100.000 = 20%. Denominator berbeda menjelaskan mengapa markup dan margin tidak sama.',[
 ['Rp100.000 dan 20%','Menambahkan markup biaya lalu membagi laba kotor dengan harga jual.'],['Rp100.000 dan 25%','Harga benar, tetapi margin memakai denominator biaya secara keliru.'],['Rp106.667 dan 25%','Ini mendekati harga untuk target margin 25%, bukan markup biaya 25%.'],['Rp95.000 dan 15%','Tidak mengikuti markup 25% dari biaya Rp80.000.']]);
tf(8,'First-mover advantage','s6','Pelopor pasar dapat memperoleh pengenalan merek lebih awal sekaligus menanggung biaya eksperimen dan edukasi pasar yang tinggi.',true,'Keuntungan waktu masuk tidak menghilangkan biaya menjadi pelopor. Keunggulan dan beban dapat muncul bersamaan; pengikut bahkan bisa belajar dari eksperimen awal.');
tf(8,'Digital currency','s5','Karena alat pembayaran berbentuk digital, barang yang dapat dibeli dengannya secara konseptual harus berupa produk digital juga.',false,'Bentuk instrumen pembayaran dan bentuk barang merupakan dua dimensi berbeda. Pembayaran digital dapat mendukung pertukaran barang fisik jika para pihak serta sistem menerimanya.');
tf(8,'Assessment dan improvement','s7','Dalam siklus strategi, assessment membandingkan hasil dengan sasaran, sedangkan improvement memilih serta menjalankan tindak lanjut atas temuan.',true,'Evaluasi mengidentifikasi kesenjangan; perbaikan menindaklanjutinya. Keduanya memberi umpan balik untuk putaran strategi berikut, dan tidak harus menunggu semua aktivitas organisasi berhenti.');

export { questions, mc, tf };
